17	package org.springframework.samples.petclinic.rest.controller.v1;
18	
19	import java.util.Collection;
20	import java.util.List;
21	
22	import org.springframework.http.HttpHeaders;
23	import org.springframework.http.HttpStatus;
24	import org.springframework.http.ResponseEntity;
25	import org.springframework.samples.petclinic.mapper.OwnerMapper;
26	import org.springframework.samples.petclinic.mapper.PetMapper;
27	import org.springframework.samples.petclinic.mapper.VisitMapper;
28	import org.springframework.samples.petclinic.model.Owner;
29	import org.springframework.samples.petclinic.model.Pet;
30	import org.springframework.samples.petclinic.model.Visit;
31	import org.springframework.samples.petclinic.rest.api.OwnersApi;
32	import org.springframework.samples.petclinic.rest.dto.OwnerDto;
33	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
34	import org.springframework.samples.petclinic.rest.dto.PetDto;
35	import org.springframework.samples.petclinic.rest.dto.PetFieldsDto;
36	import org.springframework.samples.petclinic.rest.dto.VisitDto;
37	import org.springframework.samples.petclinic.rest.dto.VisitFieldsDto;
38	import org.springframework.samples.petclinic.service.ClinicService;
39	import org.springframework.samples.petclinic.service.IdempotencyStore;
40	import org.springframework.samples.petclinic.service.OwnerAuditor;
41	import org.springframework.samples.petclinic.service.WelcomeNotifier;
42	import org.springframework.security.access.prepost.PreAuthorize;
43	import org.springframework.web.bind.annotation.CrossOrigin;
44	import org.springframework.web.bind.annotation.RequestMapping;
45	import org.springframework.web.bind.annotation.RestController;
46	import org.springframework.web.util.UriComponentsBuilder;
47	
48	import jakarta.servlet.http.HttpServletRequest;
49	import jakarta.transaction.Transactional;
50	
51	/**
52	 * @author Vitaliy Fedoriv
53	 */
54	
55	@RestController
56	@CrossOrigin(exposedHeaders = "errors, content-type")
57	@RequestMapping("/api")
58	public class OwnerRestControllerV1 implements OwnersApi {
59	
60	    private final ClinicService clinicService;
61	
62	    private final OwnerMapper ownerMapper;
63	
64	    private final PetMapper petMapper;
65	
66	    private final VisitMapper visitMapper;
67	
68	    private final OwnerAuditor ownerAuditor;
69	
70	    private final WelcomeNotifier welcomeNotifier;
71	
72	    private final IdempotencyStore idempotencyStore;
73	
74	    private final HttpServletRequest request;
75	
76	    public OwnerRestControllerV1(ClinicService clinicService,
77	                                 OwnerMapper ownerMapper,
78	                                 PetMapper petMapper,
79	                                 VisitMapper visitMapper,
80	                                 OwnerAuditor ownerAuditor,
81	                                 WelcomeNotifier welcomeNotifier,
82	                                 IdempotencyStore idempotencyStore,
83	                                 HttpServletRequest request) {
84	        this.clinicService = clinicService;
85	        this.ownerMapper = ownerMapper;
86	        this.petMapper = petMapper;
87	        this.visitMapper = visitMapper;
88	        this.ownerAuditor = ownerAuditor;
89	        this.welcomeNotifier = welcomeNotifier;
90	        this.idempotencyStore = idempotencyStore;
91	        this.request = request;
92	    }
93	
94	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
95	    @Override
96	    public ResponseEntity<List<OwnerDto>> listOwners(String lastName) {
97	        Collection<Owner> owners;
98	        if (lastName != null) {
99	            owners = this.clinicService.findOwnerByLastName(lastName);
100	        } else {
101	            owners = this.clinicService.findAllOwners();
102	        }
103	        if (owners.isEmpty()) {
104	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
105	        }
106	        return new ResponseEntity<>(ownerMapper.toOwnerDtoCollection(owners), HttpStatus.OK);
107	    }
108	
109	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
110	    @Override
111	    public ResponseEntity<OwnerDto> getOwner(Integer ownerId) {
112	        Owner owner = this.clinicService.findOwnerById(ownerId);
113	        if (owner == null) {
114	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
115	        }
116	        return new ResponseEntity<>(ownerMapper.toOwnerDto(owner), HttpStatus.OK);
117	    }
118	
119	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
120	    @Override
121	    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto) {
122	        String idempotencyKey = this.request.getHeader("Idempotency-Key");
123	        ResponseEntity<OwnerDto> replay = replayCreatedOwner(idempotencyKey);
124	        if (replay != null) {
125	            return replay;
126	        }
127	        HttpHeaders headers = new HttpHeaders();
128	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
129	        if (this.clinicService.isRegistrationDateInFuture(owner.getRegistrationDate())) {
130	            return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
131	        }
132	        owner.setRegistrationDate(this.clinicService.resolveRegistrationDate(owner.getRegistrationDate()));
133	        if (this.clinicService.isDailyOwnerLimitReached(owner.getRegistrationDate())) {
134	            return new ResponseEntity<>(HttpStatus.TOO_MANY_REQUESTS);
135	        }
136	        if (this.clinicService.isCityAtCapacity(owner.getCity())) {
137	            return new ResponseEntity<>(HttpStatus.CONFLICT);
138	        }
139	        // Assign the deterministic householdId (derived from last name and postcode) so owners in
140	        // the same household share it automatically.
141	        this.clinicService.assignHousehold(owner);
142	        boolean declaredHouseholdMember = Boolean.TRUE.equals(ownerFieldsDto.getSharesHousehold());
143	        // Reject an exact duplicate: an owner whose whole identity key (normalized telephone,
144	        // email and the Soundex of the last name) already exists.
145	        if (this.clinicService.existsOwnerWithIdentityKey(owner)) {
146	            return new ResponseEntity<>(HttpStatus.CONFLICT);
147	        }
148	        owner.setNamesakeCount((int) this.clinicService.countNamesakes(owner.getFirstName(), owner.getLastName()));
149	        owner.setHouseholdSize((int) this.clinicService.countHouseholdMembers(owner));
150	        // Cap the membership level so a new household member never outranks its household by more
151	        // than one level above its current highest-ranked member.
152	        owner.setMembershipLevel(this.clinicService.resolveCappedMembershipLevel(owner));
153	        owner.setBulkSignupWarning(this.clinicService.isBulkSignupWarranted(owner.getRegistrationDate()));
154	        owner.setCapacityWarning(this.clinicService.isCityApproachingCapacity(owner.getCity()));
155	        // Flag a soft match unless this is a declared household member (a declared member is not a
156	        // suspected duplicate): an existing owner sharing this owner's postcode and last-name Soundex
157	        // with a different identity key.
158	        if (!declaredHouseholdMember) {
159	            Integer possibleDuplicateOf = this.clinicService.findPossibleDuplicateOwnerId(owner);
160	            owner.setPossibleDuplicate(possibleDuplicateOf != null);
161	            owner.setPossibleDuplicateOf(possibleDuplicateOf);
162	        }
163	        this.clinicService.saveOwner(owner);
164	        this.ownerAuditor.auditCreated(owner);
165	        this.welcomeNotifier.enqueueWelcome(owner);
166	        this.idempotencyStore.record(idempotencyKey, owner.getId());
167	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
168	        headers.setLocation(UriComponentsBuilder.newInstance()
169	            .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
170	        return new ResponseEntity<>(ownerDto, headers, HttpStatus.CREATED);
171	    }
172	
173	    /**
174	     * If {@code idempotencyKey} was already used to create an owner, return that original owner
175	     * with {@code 200 OK} so a repeated create replays the first result instead of creating a
176	     * duplicate. Returns {@code null} when there is nothing to replay (no key, or key unseen).
177	     */
178	    private ResponseEntity<OwnerDto> replayCreatedOwner(String idempotencyKey) {
179	        return this.idempotencyStore.find(idempotencyKey)
180	            .map(this.clinicService::findOwnerById)
181	            .map(owner -> new ResponseEntity<>(ownerMapper.toOwnerDto(owner), HttpStatus.OK))
182	            .orElse(null);
183	    }
